    INSERT INTO `tmp_fp209_after_5` (`id`, `template_revision_id`, `task_code`, `name`, `parent_task_code`, `stage_code`, `priority`, `sort_order`, `estimated_hours`, `satisfaction_timing`, `description`, `stage_definition_key`, `task_definition_key`, `parent_task_definition_key`, `work_binding_type_code`, `target_context_code`, `target_object_type`, `target_object_key`, `component_key`, `dynamic_form_revision_id`, `approval_definition_key`, `binding_config`, `permission_policy_ref`, `completion_rule_type_code`, `completion_rule_config`, `gate_ref`, `definition_version`, `definition_revision_id`, `work_binding_revision_id`, `permission_policy_revision_id`, `completion_rule_revision_id`, `tenant_id`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `deleted_time`) VALUES
        (993009000057, 993009000006, 'FPROJ009_SAMPLE_DS_ENG_S1_PRE02', '现场工勘', NULL, 'S1', 2, 0, NULL, NULL, '业务目标：明确现场条件和实施就绪基线。办理功能：采集工勘分工、现场条件和就绪信息，引用项目有效工期。业务产出：工勘报告与就绪快照。优先业务结果，无重复上传；Owner已有结果时复用其有效版本，不另造上传任务。办理界面待绑定；DRAFT仅为业务配置，不创建业务实体或完成事实。TASK_NATIVE/STAGE_NATIVE不代表Owner业务已接入，绑定真实页面/表单及完成依据前不得投用。Requirement: PRE-02', 'S1', 'FPROJ009_SAMPLE_DS_ENG_S1_PRE02', NULL, 'TASK_NATIVE', NULL, NULL, NULL, NULL, NULL, NULL, '{"bindingType":"TASK_NATIVE","contextMapping":{},"instanceResolutionStrategy":"CREATE_ON_ENTER"}', 'FPROJ009_SAMPLE_VIEW_POLICY', 'TASK_NATIVE_STATUS', '{"requiredStatus":"DONE"}', NULL, 2, 993009200000, 993009000002, 993009000004, 993009000003, 1, 'fproj009-samples-20260909', '2026-09-09 00:00:00', 'fproj009-task-correction', '2026-09-09 00:00:00', b'0', NULL),
        (993009000062, 993009000006, 'FPROJ009_SAMPLE_DS_ENG_S1_PRE04', '需求分析', NULL, 'S1', 2, 10, NULL, NULL, '业务目标：形成可用于方案编制的需求基线。办理功能：填写、确认需求分析并查看有效版本。业务产出：需求分析。优先业务结果，无重复上传；Owner已有结果时复用其有效版本，不另造上传任务。办理界面待绑定；DRAFT仅为业务配置，不创建业务实体或完成事实。TASK_NATIVE/STAGE_NATIVE不代表Owner业务已接入，绑定真实页面/表单及完成依据前不得投用。Requirement: PRE-04', 'S1', 'FPROJ009_SAMPLE_DS_ENG_S1_PRE04', NULL, 'TASK_NATIVE', NULL, NULL, NULL, NULL, NULL, NULL, '{"bindingType":"TASK_NATIVE","contextMapping":{},"instanceResolutionStrategy":"CREATE_ON_ENTER"}', 'FPROJ009_SAMPLE_VIEW_POLICY', 'TASK_NATIVE_STATUS', '{"requiredStatus":"DONE"}', NULL, 2, 993009200004, 993009000002, 993009000004, 993009000003, 1, 'fproj009-samples-20260909', '2026-09-09 00:00:00', 'fproj009-task-correction', '2026-09-09 00:00:00', b'0', NULL),
        (993009000067, 993009000006, 'FPROJ009_SAMPLE_DS_ENG_S1_KICKOFF', '工程启动会', NULL, 'S1', 2, 20, NULL, NULL, '业务目标：按工程适用范围明确交付分工与目标。办理功能：按需组织启动会并记录共识；本项可选，不作为统一准出条件。业务产出：会议共识（按需记录，不要求独立文件）。优先业务结果，无重复上传；Owner已有结果时复用其有效版本，不另造上传任务。办理界面待绑定；DRAFT仅为业务配置，不创建业务实体或完成事实。TASK_NATIVE/STAGE_NATIVE不代表Owner业务已接入，绑定真实页面/表单及完成依据前不得投用。Requirement: PM-03/PRD3.2', 'S1', 'FPROJ009_SAMPLE_DS_ENG_S1_KICKOFF', NULL, 'TASK_NATIVE', NULL, NULL, NULL, NULL, NULL, NULL, '{"bindingType":"TASK_NATIVE","contextMapping":{},"instanceResolutionStrategy":"CREATE_ON_ENTER"}', 'FPROJ009_SAMPLE_VIEW_POLICY', 'TASK_NATIVE_STATUS', '{"requiredStatus":"DONE"}', NULL, 2, 993009200008, 993009000002, 993009000004, 993009000003, 1, 'fproj009-samples-20260909', '2026-09-09 00:00:00', 'fproj009-task-correction', '2026-09-09 00:00:00', b'0', NULL),
        (993009000118, 993009000006, 'FPROJ009_SAMPLE_DS_ENG_S2_PLN01', '施工计划制定', NULL, 'S2', 2, 0, NULL, NULL, '业务目标：形成审批通过的可执行施工计划。办理功能：读取有效工期，推算建议时间、调整计划、超期提示、提交与审批，并查看审批结果。业务产出：施工计划及审批事实。优先业务结果，无重复上传；Owner已有结果时复用其有效版本，不另造上传任务。办理界面待绑定；DRAFT仅为业务配置，不创建业务实体或完成事实。TASK_NATIVE/STAGE_NATIVE不代表Owner业务已接入，绑定真实页面/表单及完成依据前不得投用。Requirement: PLN-01/PLN-02/PLN-03/PLN-04', 'S2', 'FPROJ009_SAMPLE_DS_ENG_S2_PLN01', NULL, 'TASK_NATIVE', NULL, NULL, NULL, NULL, NULL, NULL, '{"bindingType":"TASK_NATIVE","contextMapping":{},"instanceResolutionStrategy":"CREATE_ON_ENTER"}', 'FPROJ009_SAMPLE_VIEW_POLICY', 'TASK_NATIVE_STATUS', '{"requiredStatus":"DONE"}', NULL, 2, 993009200012, 993009000002, 993009000004, 993009000003, 1, 'fproj009-samples-20260909', '2026-09-09 00:00:00', 'fproj009-task-correction', '2026-09-09 00:00:00', b'0', NULL),
        (993009000153, 993009000006, 'FPROJ009_SAMPLE_DS_ENG_S3_PLAN', '实施方案编审', NULL, 'S3', 2, 0, NULL, NULL, '业务目标：形成审核通过的实施方案。办理功能：编辑方案、导入客户方案、引用配置脚本和拓扑、提交审核、查看版本；重大复审按真实适用条件办理。业务产出：批准方案及审核版本。优先业务结果，无重复上传；Owner已有结果时复用其有效版本，不另造上传任务。办理界面待绑定；DRAFT仅为业务配置，不创建业务实体或完成事实。TASK_NATIVE/STAGE_NATIVE不代表Owner业务已接入，绑定真实页面/表单及完成依据前不得投用。Requirement: SCH-01/SCH-02/SCH-05/PRD3.1.4', 'S3', 'FPROJ009_SAMPLE_DS_ENG_S3_PLAN', NULL, 'TASK_NATIVE', NULL, NULL, NULL, NULL, NULL, NULL, '{"bindingType":"TASK_NATIVE","contextMapping":{},"instanceResolutionStrategy":"CREATE_ON_ENTER"}', 'FPROJ009_SAMPLE_VIEW_POLICY', 'TASK_NATIVE_STATUS', '{"requiredStatus":"DONE"}', NULL, 2, 993009200016, 993009000002, 993009000004, 993009000003, 1, 'fproj009-samples-20260909', '2026-09-09 00:00:00', 'fproj009-task-correction', '2026-09-09 00:00:00', b'0', NULL),
        (993009000188, 993009000006, 'FPROJ009_SAMPLE_DS_ENG_S4_EXE01', '到货验收', NULL, 'S4', 2, 0, NULL, NULL, '业务目标：确认实际到货与交付范围一致。办理功能：现场核验到货并登记签收及差异。业务产出：到货签收单或现场验货单。优先业务结果，无重复上传；Owner已有结果时复用其有效版本，不另造上传任务。办理界面待绑定；DRAFT仅为业务配置，不创建业务实体或完成事实。TASK_NATIVE/STAGE_NATIVE不代表Owner业务已接入，绑定真实页面/表单及完成依据前不得投用。Requirement: EXE-01', 'S4', 'FPROJ009_SAMPLE_DS_ENG_S4_EXE01', NULL, 'TASK_NATIVE', NULL, NULL, NULL, NULL, NULL, NULL, '{"bindingType":"TASK_NATIVE","contextMapping":{},"instanceResolutionStrategy":"CREATE_ON_ENTER"}', 'FPROJ009_SAMPLE_VIEW_POLICY', 'TASK_NATIVE_STATUS', '{"requiredStatus":"DONE"}', NULL, 2, 993009200020, 993009000002, 993009000004, 993009000003, 1, 'fproj009-samples-20260909', '2026-09-09 00:00:00', 'fproj009-task-correction', '2026-09-09 00:00:00', b'0', NULL),
